#!/bin/sh
# ARCADE-1 — walkdemo test: the walking-spritesheet experiment's mechanics.
#
# walkdemo (programs/experimental/walkdemo.c) blits a 40x56 4-bit character
# from a 7-frame sheet generated by tools/gen_walk_sheet.py. Findings:
# docs/experiments/walkdemo.md. This test pins what the experiment claimed:
#
#   1. idle      — nothing held: no movement, no animation, a stable picture
#   2. walk      — holding right: exactly SPEED px/frame, facing 0, the walk
#                  cycle advances through 1..6 and the picture changes
#   3. flip      — the blitter's free flip-X mirrors the art: the pupil is
#                  at sheet column 23 walking right and at 39-23=16 walking
#                  left, so one sheet serves both directions
#
# The character's eye is the probe for all of this: 2 pupil-coloured pixels
# (RGB888 8,4,49 = RGB565 1,1,6) at a known sheet column.
#
# usage: test_walkdemo.sh <arcade1-cli> <rom-dir>
#
# NOTE: walkdemo is an EXPERIMENT (built by `make experimental`, not by
# `make check`); this test is likewise run by hand: `make test-walkdemo`.

set -eu

CLI=${1:?usage: test_walkdemo.sh <arcade1-cli> <rom-dir>}
ROM=${2:?}

OUT=$(mktemp -d)
trap 'rm -rf "$OUT"' EXIT

fail() { echo "test-walkdemo: FAILED — $1" >&2; exit 1; }
note() { echo "  $1"; }

GAME=$ROM/walkdemo.arc1

[ -x "$CLI" ]  || fail "CLI not built at $CLI"
[ -f "$GAME" ] || fail "missing $GAME (make experimental)"

SYMS=$ROM/walkdemo.syms
if [ ! -f "$SYMS" ] && [ -f "$ROM/walkdemo.elf" ] &&
   command -v riscv64-unknown-elf-nm >/dev/null 2>&1; then
    riscv64-unknown-elf-nm "$ROM/walkdemo.elf" > "$OUT/walkdemo.syms"
    SYMS="$OUT/walkdemo.syms"
fi
[ -f "$SYMS" ] || fail "no walkdemo.syms and no riscv nm to make one"

X0=20        # the guest's starting x
SPEED=2      # px per frame
PUPIL="8 4 49"   # RGB888 of palette entry 7 (RGB565 1,1,6)
SKIN="230 178 148"   # RGB888 of palette entry 4 (RGB565 28,44,18)

# scan_pupil <ppm> <char-x> -> "count min_rel_x max_rel_x skin_count"
# Pupil/skin pixels inside the character's box (sheet y 0..55 = screen
# y 146..201, the sprite is drawn at GROUND_Y-H+2 = 146).
scan_pupil() {
    tail -c $((480 * 270 * 3)) "$1" | od -An -v -tu1 | awk \
        -v cx="$2" -v pr="$3" -v pg="$4" -v pb="$5" \
        -v sr="$6" -v sg="$7" -v sb="$8" '
        { for (i = 1; i <= NF; i++) { c[n % 3] = $i; n++
            if (n % 3 == 0) {
                p = int(n / 3) - 1; x = p % 480; y = int(p / 480)
                if (y >= 146 && y < 205 && x >= cx - 4 && x < cx + 44) {
                    if (c[0] == pr && c[1] == pg && c[2] == pb) {
                        cnt++; rx = x - cx
                        if (mn == "" || rx < mn) mn = rx
                        if (mx == "" || rx > mx) mx = rx
                    }
                    if (c[0] == sr && c[1] == sg && c[2] == sb) skin++
                } } } }
        END { printf "%d %s %s %d\n", cnt + 0, (mn == "" ? "-" : mn), \
             (mx == "" ? "-" : mx), skin + 0 }'
}

# --- 1) idle: 12 frames, nothing held ----------------------------------------
"$CLI" run "$GAME" --frames 12 --syms "$SYMS" --vars x,facing,anim,moving \
    > "$OUT/idle.txt" 2>/dev/null || fail "idle run failed"
NFB=$(grep '^frame ' "$OUT/idle.txt" | awk '{print $4}' | sort -u | wc -l | tr -d ' ')
[ "$NFB" = "1" ] || fail "idle picture is not stable ($NFB distinct fb hashes in 12 frames)"
grep -q '^var x = 20$'   "$OUT/idle.txt" || fail "idle: x drifted"
grep -q '^var anim = 0$' "$OUT/idle.txt" || fail "idle: animation ran without input"
grep -q '^var moving = 0$' "$OUT/idle.txt" || fail "idle: moving set without input"
note "idle ok — 12 frames, one fb hash, no movement, anim 0"

# --- 2) walk right: 40 frames of BTN_RIGHT -----------------------------------
printf '0 39 right\n' > "$OUT/right.txt"
"$CLI" run "$GAME" --frames 40 --input "$OUT/right.txt" --syms "$SYMS" \
    --vars x,facing,anim,moving --var-every 1 \
    > "$OUT/walk.txt" 2>/dev/null || fail "walk-right run failed"

grep -q '^var x = 100$' "$OUT/walk.txt" ||
    fail "pace: expected x=100 after 40 frames at 2px (got $(grep '^var x' "$OUT/walk.txt"))"
grep -q '^var facing = 0$' "$OUT/walk.txt" || fail "walking right: facing != 0"
grep -q '^var moving = 1$' "$OUT/walk.txt" || fail "walking right: moving not set"

grep '^vars' "$OUT/walk.txt" | sed -n 's/.*anim=\([0-9]*\).*/\1/p' > "$OUT/anims.txt"
BAD=$(awk '$1 < 1 || $1 > 6' "$OUT/anims.txt" | wc -l | tr -d ' ')
[ "$BAD" = "0" ] || fail "walk cycle left the sheet (values 1..6 only)"
DISTINCT=$(sort -un "$OUT/anims.txt" | wc -l | tr -d ' ')
[ "$DISTINCT" -ge 3 ] || fail "walk cycle did not advance ($DISTINCT distinct steps in 40 frames)"
NFB=$(grep '^frame ' "$OUT/walk.txt" | awk '{print $4}' | sort -u | wc -l | tr -d ' ')
[ "$NFB" -ge 4 ] || fail "picture barely changed while walking ($NFB distinct fb hashes)"
note "walk ok — 2px/frame to x=100, cycle 1..6, $NFB distinct pictures"

# --- 3) flip-X: the pupil must mirror when walking left ----------------------
# Right-facing capture: pupil at sheet column 23 (char-relative).
"$CLI" run "$GAME" --frames 40 --input "$OUT/right.txt" --syms "$SYMS" \
    --vars x --capture "$OUT/right.ppm" --quiet > "$OUT/rcap.txt" 2>/dev/null ||
    fail "right capture run failed"
RX=$(sed -n 's/^var x = \([0-9]*\)$/\1/p' "$OUT/rcap.txt")
set -- $(scan_pupil "$OUT/right.ppm" "$RX" $PUPIL $SKIN)
[ "$1" -eq 2 ] || fail "right-facing: want 2 pupil px, got $1"
[ "$2" = "23" ] && [ "$3" = "23" ] ||
    fail "right-facing: pupil at rel-x $2..$3, want 23"
[ "$4" -ge 40 ] || fail "character not drawn ($4 skin px)"
note "flip ok (right) — x=$RX, pupil at rel-x 23, $4 skin px"

# Cross run: 40 right then 40 left -> back to x=20, facing 1 (flip X).
printf '0 39 right\n40 79 left\n' > "$OUT/cross.txt"
"$CLI" run "$GAME" --frames 80 --input "$OUT/cross.txt" --syms "$SYMS" \
    --vars x,facing --capture "$OUT/left.ppm" --quiet > "$OUT/lcap.txt" 2>/dev/null ||
    fail "cross run failed"
grep -q '^var x = 20$' "$OUT/lcap.txt" ||
    fail "cross: expected x=20 after walking out and back (got $(grep '^var x' "$OUT/lcap.txt"))"
grep -q '^var facing = 1$' "$OUT/lcap.txt" || fail "walking left: facing != 1"
LX=$(sed -n 's/^var x = \([0-9]*\)$/\1/p' "$OUT/lcap.txt")
set -- $(scan_pupil "$OUT/left.ppm" "$LX" $PUPIL $SKIN)
[ "$1" -eq 2 ] || fail "left-facing: want 2 pupil px, got $1"
[ "$2" = "16" ] && [ "$3" = "16" ] ||
    fail "left-facing: pupil at rel-x $2..$3, want 16 (mirror of 23: 39-23)"
note "flip ok (left) — x=$LX, pupil mirrored to rel-x 16 (39-23)"

echo "test-walkdemo: walkdemo ok (idle, pace 2px/f, cycle 1..6, flip-X mirrors)"
